import subprocess
import sys
from langchain_core.tools import tool

SYNC_SCRIPT_PATH = "/opt/accounts/bin/sync_group.py"
ALLOWED_PERMISSION_LEVELS = ("read", "write", "manage")


@tool
def sync_group_membership_script(
    username: str, group_name: str, permission_level: str = "read"
) -> str:
    if permission_level not in ALLOWED_PERMISSION_LEVELS:
        return (
            "Invalid permission_level. Choose one of: "
            + ", ".join(ALLOWED_PERMISSION_LEVELS)
        )

    if not username.strip() or not group_name.strip():
        return "username and group_name must not be empty"

    command_arguments_list = [
        sys.executable,
        SYNC_SCRIPT_PATH,
        "--user",
        username,
        "--group",
        group_name,
        "--level",
        permission_level,
    ]

    try:
        finished_process_result = subprocess.run(
            command_arguments_list,
            capture_output=True,
            text=True,
            timeout=120,
        )
    except subprocess.TimeoutExpired:
        return "Sync script timed out after 120 seconds"

    standard_output_text = finished_process_result.stdout.strip()
    standard_error_text = finished_process_result.stderr.strip()

    if finished_process_result.returncode != 0:
        return (
            f"Sync failed with exit code {finished_process_result.returncode}: "
            f"{standard_error_text or standard_output_text}"
        )

    return (
        f"Added {username} to {group_name} with {permission_level} access. "
        f"{standard_output_text}"
    )
